-- Dados de exemplo da Lista Pronta: 1 papelaria, 2 escolas, 4 séries,
-- 22 produtos com as faixas, e as listas de 2027 publicadas.
--
-- Idempotente: UUIDs fixos e "on conflict" com alvo explícito. Rodar de novo
-- não duplica nada e devolve preços e status aos valores de exemplo.
--
-- O usuário dono da papelaria NÃO nasce aqui: conta de acesso se cria pela
-- API de autenticação (etapa c), não por insert em auth.users.
--
-- Casos de borda de propósito: o pincel não tem faixa premium, e o EVA tem a
-- premium indisponível. A lista do 3º ano do Colégio Modelo de 2026 está
-- encerrada e não pode aparecer para os pais.

  aceita_entrega, aceita_retirada, taxa_entrega_centavos)
values ('00000000-0000-4000-8000-000000000001', 'Papelaria Central', 'papelaria-central', '11900000000',
  'Rua das Flores, 100 · Centro', true, true, 1000)
on conflict (id) do update set nome = excluded.nome, slug = excluded.slug,
  whatsapp = excluded.whatsapp, endereco_retirada = excluded.endereco_retirada,
  aceita_entrega = excluded.aceita_entrega, aceita_retirada = excluded.aceita_retirada,
  taxa_entrega_centavos = excluded.taxa_entrega_centavos;

on conflict (id) do update set nome = excluded.nome, categoria = excluded.categoria,
  ordem = excluded.ordem, ativo = true;

on conflict (id) do update set marca = excluded.marca,
  preco_centavos = excluded.preco_centavos, disponivel = excluded.disponivel;

on conflict (id) do update set nome = excluded.nome, slug = excluded.slug, cidade = excluded.cidade;

on conflict (id) do update set nome = excluded.nome, slug = excluded.slug, ordem = excluded.ordem;

on conflict (id) do update set status = excluded.status, observacoes = excluded.observacoes,
  publicada_em = coalesce(public.lista.publicada_em, excluded.publicada_em),
  encerrada_em = excluded.encerrada_em;

on conflict (lista_id, produto_id) do update set quantidade = excluded.quantidade,
  observacao = excluded.observacao, ordem = excluded.ordem;
